<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use Nimbly\Capsule\Response;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthorizationRequestResolver;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ResolvedAuthorizationRequest;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Par\Infrastructure\Driver\Rest\ParController;

class ParTest extends OidcIntegrationTestCase
{
    private const string CHALLENGE = 'E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM';

    private ParController $controller;
    private AuthorizationRequestResolver $resolver;

    protected function setUp(): void
    {
        parent::setUp();
        $this->controller = $this->container->get(ParController::class);
        $this->resolver = $this->container->get(AuthorizationRequestResolver::class);
    }

    public function testValidParRequestReturns201WithRequestUri(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/par', [
            'client_id' => self::CLIENT_ID,
            'client_secret' => self::CLIENT_SECRET,
            'response_type' => 'code',
            'redirect_uri' => 'https://app.example.com/callback',
            'scope' => 'openid profile',
            'state' => 'random-state',
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(201, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertArrayHasKey('request_uri', $body);
        $this->assertArrayHasKey('expires_in', $body);
        $this->assertStringStartsWith('urn:ietf:params:oauth:request_uri:', $body['request_uri']);
        $this->assertSame(60, $body['expires_in']);
    }

    public function testParRequestUriIsStoredAndRetrievable(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/par', [
            'client_id' => self::CLIENT_ID,
            'client_secret' => self::CLIENT_SECRET,
            'response_type' => 'code',
            'redirect_uri' => 'https://app.example.com/callback',
            'scope' => 'openid',
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $body = $this->decodeJson($response);
        $requestUri = $body['request_uri'];

        $stored = $this->parStore->findByUri($requestUri, self::TENANT);

        $this->assertNotNull($stored);
        $this->assertSame($requestUri, $stored->requestUri);
        $this->assertSame(self::TENANT, $stored->tenant);
        $this->assertSame(self::CLIENT_ID, $stored->clientId);
        $this->assertFalse($stored->isExpired());
        $this->assertFalse($stored->isUsed());
    }

    public function testParRequestPreservesAuthorizationParams(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/par', [
            'client_id' => self::CLIENT_ID,
            'client_secret' => self::CLIENT_SECRET,
            'response_type' => 'code',
            'redirect_uri' => 'https://app.example.com/callback',
            'scope' => 'openid profile email',
            'nonce' => 'test-nonce',
            'state' => 'csrf-token',
            'code_challenge' => 'abc123',
            'code_challenge_method' => 'S256',
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $body = $this->decodeJson($response);
        $stored = $this->parStore->findByUri($body['request_uri'], self::TENANT);

        $this->assertSame('code', $stored->params['response_type']);
        $this->assertSame('openid profile email', $stored->params['scope']);
        $this->assertSame('test-nonce', $stored->params['nonce']);
        $this->assertSame('S256', $stored->params['code_challenge_method']);
    }

    public function testInvalidClientSecretReturns401(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/par', [
            'client_id' => self::CLIENT_ID,
            'client_secret' => 'wrong-secret',
            'response_type' => 'code',
            'redirect_uri' => 'https://app.example.com/callback',
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(401, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertSame('invalid_client', $body['error']);
    }

